        center = c(0, 0),
        zoom = 2.75,
        pitch = 0,
        bearing = 0
      )
  })

  mapgl::on_section("map", "childhood", {
    mapgl::maplibre_proxy("map") |&gt;
      mapgl::fly_to(center = c(87.99371750247397, 26.646533355308083),
